{
 "id": "viewfinder-corner-lock",
 "name": "Corner Lock Settle",
 "idea": "Four hairline corners hunt slightly wide around a card-sized region set low on phones and to the right on desktop, then settle onto it with a short damped overshoot, turn amber once at lock while the inside steps one tone lighter, hold, and release.",
 "use": [
  "card",
  "loading",
  "hero"
 ],
 "frag": "precision highp float;
uniform vec2 u_resolution;
uniform float u_time;
uniform vec3 u_c0;
uniform vec3 u_c1;
uniform vec3 u_c2;
uniform vec3 u_c3;
float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float box(vec2 p,vec2 b){vec2 d=abs(p)-b;return length(max(d,0.0))+min(max(d.x,d.y),0.0);}
void main(){
vec2 p=(gl_FragCoord.xy-0.5*u_resolution)/u_resolution.y;
float asp=u_resolution.x/u_resolution.y;
float px=1.5/u_resolution.y;
float ph=mod(u_time,10.0);
float k=max(ph-2.5,0.0);
float w=mix(1.0,exp(-k*2.2)*cos(k*5.0),step(2.5,ph));
w=max(w,smoothstep(8.6,10.0,ph));
float lock=smoothstep(3.6,4.2,ph)*(1.0-smoothstep(8.3,9.0,ph));
float wide=smoothstep(0.9,1.2,asp);
vec2 c=mix(vec2(0.0,-0.2),vec2(asp*0.2,-0.04),wide);
vec2 hs=mix(vec2(min(0.4,asp*0.4),0.11),vec2(0.34,0.17),wide);
c+=vec2(sin(u_time*0.9),cos(u_time*0.7))*0.01*max(w,0.0);
hs*=1.0+0.07*w;
vec2 q=abs(p-c);
float L=min(hs.x,hs.y)*0.36;
float th=1.0/u_resolution.y;
float s1=box(q-vec2(hs.x-L*0.5,hs.y),vec2(L*0.5,th));
float s2=box(q-vec2(hs.x,hs.y-L*0.5),vec2(th,L*0.5));
float dcm=min(s1,s2);
float cm=1.0-smoothstep(0.0,px,dcm);
float ins=1.0-smoothstep(-px,px,box(p-c,hs));
vec3 col=u_c0;
float fall=exp(-length(p-c)*2.5);
vec2 gf=fract(p/0.035)-0.5;
float dots=1.0-smoothstep(0.0025,0.0025+px,length(gf)*0.035);
col=mix(col,u_c3,dots*0.22*fall);
col=mix(col,mix(u_c0,u_c3,0.24),ins*mix(0.35,1.0,lock));
float g=h(floor(gl_FragCoord.xy))-0.5;
col+=g*mix(0.008,0.03,ins);
vec3 ink=mix(u_c3,u_c1,0.55);
vec3 cc=mix(ink,u_c2,lock);
col+=u_c2*exp(-max(dcm,0.0)*60.0)*lock*0.12;
float ty=c.y-hs.y-0.045;
float fx=(fract((p.x-c.x)/0.025+0.5)-0.5)*0.025;
float inr=step(abs(p.x-c.x),hs.x);
float td=box(vec2(fx,p.y-ty),vec2(th,0.006));
col=mix(col,ink,(1.0-smoothstep(0.0,px,td))*0.35*inr);
float mx=c.x+hs.x*0.8*clamp(w,-1.0,1.0);
float md=box(p-vec2(mx,ty+0.014),vec2(0.004,0.004));
col=mix(col,cc,1.0-smoothstep(0.0,px,md));
col=mix(col,cc,cm*mix(0.75,1.0,lock));
col*=1.0-0.18*smoothstep(0.3,1.2,length(p));
gl_FragColor=vec4(col,1.0);
}",
 "colors": [
  "#111315",
  "#e8e6df",
  "#f2b134",
  "#5c6166"
 ],
 "reduced": {
  "kind": "fade",
  "at": 5,
  "ms": 400,
  "note": "Four amber corners locked on the region with a soft glow, its inside one tone lighter over a faint dot grid, and a small focus scale beneath it."
 },
 "cardIds": [
  "corner-brackets"
 ],
 "lensIds": [],
 "styles": [
  "dark-quiet-matte"
 ]
}
