{
 "id": "swiss-baseline-reflow",
 "name": "Baseline Grid Step",
 "idea": "Faint baseline hairlines and paired gutter rules on a paper-white surface, with a few short ink ticks marking ragged line ends in one column block, while a single red rule steps down its column every three seconds and snaps onto the next baseline, a soft grey column shade steps one column across the grid in time with it, and the ragged line ends reflow to new baseline-unit positions.",
 "use": [
  "hero",
  "card",
  "paywall-plan",
  "empty-state"
 ],
 "frag": "precision highp float;
uniform vec2 u_resolution;
uniform float u_time;
uniform vec3 u_c0;
uniform vec3 u_c1;
uniform vec3 u_c2;
uniform vec3 u_c3;
float h(float n){return fract(sin(n*91.7+3.1)*43758.5453);}
float ez(float x){x=clamp(x,0.0,1.0);return 1.0-pow(1.0-x,3.0);}
float pp(float k){float q=mod(k,8.0);return q<4.5?q:8.0-q;}
void main(){
vec2 r=u_resolution,f=gl_FragCoord.xy;
float s=min(r.x,r.y);
float P=step(r.x,r.y);
float N=mix(12.0,6.0,P);
float m=0.07*s,g=0.02*s;
float cs=(r.x-2.0*m+g)/N;
float bl=max(10.0,floor(s/30.0));
float top=r.y-m;
float rows=floor((top-m)/bl);
float cx=f.x-m;
float cf=mod(cx,cs);
float by=top-f.y;
float li=floor(by/bl);
float lf=by-li*bl;
float inX=step(-1.0,cx)*step(cx,r.x-2.0*m+1.0);
float inY=step(0.0,by)*step(by,rows*bl+0.5);
float T=u_time/3.0,k=floor(T),fr=fract(T);
float w=ez(fr/0.25);
vec3 col=u_c0;
float ci=floor(cx/cs);
float a=mod(k,N),b=mod(k-1.0,N);
float hl=(1.0-step(0.5,abs(ci-a)))*w+(1.0-step(0.5,abs(ci-b)))*(1.0-w);
float cm=smoothstep(-0.75,0.75,cf)*(1.0-smoothstep(cs-g-0.75,cs-g+0.75,cf))*step(0.0,cx)*inY;
col=mix(col,u_c3,hl*cm*0.12);
float d1=min(min(abs(cf),abs(cf-cs)),abs(cf-(cs-g)));
float cr=(1.0-smoothstep(0.2,1.0,d1))*inY*inX;
float d2=min(lf,bl-lf);
float bs=(1.0-smoothstep(0.2,1.0,d2))*inY*step(0.0,cx)*step(cx,r.x-2.0*m);
col=mix(col,u_c3,bs*0.08);
col=mix(col,u_c3,cr*0.14);
float bx0=m+mix(1.0,0.0,P)*cs;
float meas=5.0*cs-g;
float r0=3.0,r1=floor(rows*mix(0.62,0.4,P));
float lp=mod(li-r0,6.0);
float on=step(r0,li)*step(li,r1)*step(lp,4.5)*step(0.35,h(li*3.1));
float t0=floor(meas*(0.45+0.5*h(li*1.7+k*7.3))/bl)*bl;
float t1=floor(meas*(0.45+0.5*h(li*1.7+(k-1.0)*7.3))/bl)*bl;
float tx=bx0+mix(t1,t0,w);
float tk=(1.0-smoothstep(0.6,1.4,abs(f.x-tx)))*smoothstep(bl*0.55-0.75,bl*0.55+0.75,lf)*on;
col=mix(col,u_c1,tk*0.5);
float sl=floor((r1-r0)/4.0);
float ly=(r0+mix(pp(k-1.0),pp(k),w)*sl)*bl;
float th=max(4.0,floor(bl*0.34));
float dx=f.x-bx0;
float rr=(1.0-smoothstep(th*0.5-0.75,th*0.5+0.75,abs(by-(ly-th*0.5-1.0))))*smoothstep(-0.75,0.75,dx)*(1.0-smoothstep(cs-g-0.75,cs-g+0.75,dx));
col=mix(col,u_c2,rr);
float gr=fract(sin(dot(f,vec2(12.9898,78.233)))*43758.5453)-0.5;
col+=gr*0.016;
gl_FragColor=vec4(col,1.0);
}
",
 "colors": [
  "#f5f5f2",
  "#111111",
  "#d7261e",
  "#6b6b6b"
 ],
 "reduced": {
  "kind": "static",
  "at": 2,
  "note": "A quiet paper-white grid of hairline baselines and gutter rules, with a few ink ticks, the first column softly shaded and one red rule resting at the top of its column."
 },
 "cardIds": [
  "swiss-style-1960s"
 ],
 "lensIds": [
  "swiss-international"
 ],
 "culturalNotes": "Follows the International Typographic Style, shaped in Zurich and Basel in the 1950s and 1960s by Swiss designers and teachers, among them Josef Müller-Brockmann, Armin Hofmann and Emil Ruder. It borrows the structure behind the page, not the page itself. It uses a twelve column grid on desktop and six on a phone, with equal gutters drawn as paired hairlines, and a fixed baseline drawn as faint rules. A few short ticks snap to the baseline unit to carry the flush-left, ragged-right rhythm. Whole columns and the lower field stay empty on purpose. A faint grey column shade steps across the grid to show the columns, and a single sharp red rule is the only accent. Its motion snaps to the grid. No letters, text bars, flags, crosses or copied posters are drawn.",
 "styles": [
  "minimal-mono-light"
 ]
}
