```json
{
 "id": "najdi-crenel-stack",
 "name": "Plaster Cut Row",
 "idea": "A wide matte plaster surface with fine grain and one soft raking light that drifts slowly across it, crossed low by one row of small equal triangle cuts that light up in the accent left to right in short stepped beats, hold, then fade together and start again.",
 "use": [
  "hero",
  "header",
  "loading",
  "onboarding-slide"
 ],
 "frag": "precision highp float;
uniform vec2 u_resolution;
uniform float u_time;
uniform vec3 u_c0;
uniform vec3 u_c1;
uniform vec3 u_c2;
uniform vec3 u_c3;
float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float n(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(h(i),h(i+vec2(1.0,0.0)),f.x),mix(h(i+vec2(0.0,1.0)),h(i+vec2(1.0,1.0)),f.x),f.y);}
float tri(vec2 p,float r){const float k=1.7320508;p.x=abs(p.x)-r;p.y=p.y+r/k;if(p.x+k*p.y>0.0)p=vec2(p.x-k*p.y,-k*p.x-p.y)/2.0;p.x-=clamp(p.x,-2.0*r,0.0);return -length(p)*sign(p.y);}
void main(){
vec2 r=u_resolution;vec2 p=(gl_FragCoord.xy-0.5*r)/r.y;float px=1.5/r.y;float t=u_time;
float a=r.x/r.y;
float m=n(p*2.5+vec2(t*0.04,0.0))*0.6+n(p*6.0-vec2(0.0,t*0.03))*0.4;
vec3 col=mix(u_c0,u_c3,0.08*m)*(0.97+0.05*m);
vec2 lc=vec2(0.42*a*sin(t*0.45),0.12+0.1*sin(t*0.31));
vec2 d=(p-lc)*vec2(1.0/max(a,0.6),1.0);
float L=exp(-dot(d,d)*3.0);
col=col*(0.86+0.24*L)+u_c3*0.05*L;
float yc=-0.3;
col=mix(col,col*0.9,smoothstep(px,-px,p.y-(yc-0.04)));
float P=0.05;
float N=floor(a/P);
float off=(a-N*P)*0.5;
float x=p.x+0.5*a-off;
float ci=floor(x/P);
float inr=step(0.0,ci)*step(ci,N-1.0);
vec2 q=vec2((fract(x/P)-0.5)*P,p.y-yc);
float cut=smoothstep(px,-px,tri(q,0.014))*inr;
float ph=fract(t/14.0);
float k=clamp(ph/0.7,0.0,1.0)*8.0;
float s=(floor(k)+smoothstep(0.0,0.35,fract(k)))/8.0;
float fade=1.0-smoothstep(0.9,1.0,ph);
float on=clamp(s*N-ci,0.0,1.0)*fade;
float z=(p.y-yc)/0.045;
float band=exp(-z*z);
col=mix(col,u_c2,0.1*band*on*inr);
vec3 imp=mix(col,u_c1,0.07);
vec3 lit=mix(u_c2,u_c1,0.06);
col=mix(col,mix(imp,lit,on),cut);
col+=(h(floor(gl_FragCoord.xy))-0.5)*0.03;
gl_FragColor=vec4(col,1.0);}
",
 "colors": [
  "#3b2a1e",
  "#f3ebdd",
  "#a8432f",
  "#b98a5e"
 ],
 "reduced": {
  "kind": "fade",
  "at": 10,
  "ms": 400,
  "note": "The plain plaster surface fades in with a soft light at the left and the full row of triangle cuts lit in the accent."
 },
 "cardIds": [
  "najdi-mud-architecture"
 ],
 "lensIds": [
  "najdi"
 ],
 "culturalNotes": "Follows Najdi architecture, the mud-brick earth building tradition of the builders and families of Najd in central Arabia. It borrows only the grammar: a large plain mass that stays far bigger than the pattern, and one strict row of small equal triangle cuts set at a true repeat so each cut lands on the same step. The stepped reveal borrows the lens verb, stack up, as a rhythm, not as a picture of building. It draws no wall, roofline, door or real building. At-Turaif District in ad-Dir'iyah is inscribed by UNESCO as a World Heritage site, and this shader is not endorsed by the site.",
 "styles": [
  "gulf-arabic-first"
 ]
}
